const result=(value,status=200,extra={})=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...extra}});
const clean=(v,max=200)=>typeof v==='string'?v.trim().slice(0,max):'';
const uuid=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/i.test(v);
const now=()=>new Date().toISOString();const hex=bytes=>[...bytes].map(b=>b.toString(16).padStart(2,'0')).join('');const hash=async s=>hex(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))));
function secret(){return hex(crypto.getRandomValues(new Uint8Array(32)));}
async function bytes(request,max){const reader=request.body?.getReader();if(!reader)return new Uint8Array();let all=[],n=0;while(true){const {done,value}=await reader.read();if(done)break;n+=value.length;if(n>max){await reader.cancel();throw Error('File or request is too large.');}all.push(value);}let data=new Uint8Array(n),offset=0;for(const c of all){data.set(c,offset);offset+=c.length;}return data;}
async function input(request,max=250000){if(!request.headers.get('Content-Type')?.startsWith('application/json'))throw Error('Use JSON.');return JSON.parse(new TextDecoder().decode(await bytes(request,max)));}
async function settings(db,key,fallback){const row=await db.prepare('SELECT value FROM site_settings WHERE key = ?').bind(key).first();return row?JSON.parse(row.value):fallback;}
async function setSettings(db,key,value){await db.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').bind(key,JSON.stringify(value),now()).run();}
export async function getRule(db,id){const r=await db.prepare('SELECT config,revision FROM pricing_rules WHERE id = ?').bind(id).first();if(r)return upgradeRule({...JSON.parse(r.config),revision:r.revision});const fallback=[...DEFAULT_RULES,...EXTRA_RULES,...APPAREL_RULES].find(r=>r.id===id);if(!fallback)throw Error('Pricing form not found.');let rule=structuredClone(fallback);if(id.startsWith('wrap-')){const legacy=await settings(db,'pricing',null);if(legacy){rule.constants.base=legacy.bases[id.slice(5)]??rule.constants.base;rule.constants.roofMultiplier=legacy.roofMultiplier;rule.constants.designDeposit=legacy.designDeposit;}}return upgradeRule(rule);}
async function allRules(db){const saved=await db.prepare('SELECT id,config,revision FROM pricing_rules ORDER BY id').all();const rows=[];for(const d of [...DEFAULT_RULES,...EXTRA_RULES,...APPAREL_RULES])rows.push(await getRule(db,d.id));for(const r of saved.results)if(![...DEFAULT_RULES,...EXTRA_RULES,...APPAREL_RULES].some(d=>d.id===r.id))rows.push({...JSON.parse(r.config),revision:r.revision});return rows;}
export async function quote(db,id,values,code){const rule=await getRule(db,id);validateRule(rule);if(id==='wrap-prints'&&Number(values.kind)===1&&Number(values.height)>48)throw Error('Cut decals have a maximum height of 48 inches.');let coupon=null;if(code){coupon=(await settings(db,'discount_codes',[])).find(c=>c.code===String(code).trim().toUpperCase());if(!coupon)throw Error('Discount code not found.');}return calculate(rule,values,coupon);}
export async function session(request,db){const cookie=request.headers.get('Cookie')?.match(/(?:^|;\s*)satin_studio=([a-f0-9-]{36})\.([a-f0-9]{64})(?:;|$)/);if(!cookie)return null;const s=await db.prepare('SELECT * FROM studio_sessions WHERE id = ? AND expires_at > ?').bind(cookie[1],now()).first();return s&&s.token_hash===await hash(cookie[2])?s:null;}
export async function fileRow(db,id,sessionId,admin){const row=await db.prepare('SELECT * FROM studio_files WHERE id = ?').bind(id).first();if(!row||!admin&&row.session_id!==sessionId)throw Error('File not found.');return row;}
function mime(data){if(data[0]===137&&data[1]===80&&data[2]===78&&data[3]===71)return 'image/png';if(data[0]===255&&data[1]===216&&data[2]===255)return 'image/jpeg';if(String.fromCharCode(...data.slice(0,4))==='RIFF'&&String.fromCharCode(...data.slice(8,12))==='WEBP')return 'image/webp';if(String.fromCharCode(...data.slice(0,5))==='%PDF-')return 'application/pdf';const svg=new TextDecoder().decode(data);if(/^(?:\s*<\?xml[^>]*>\s*)?\s*<svg[\s>]/i.test(svg)){if(/<!DOCTYPE|<!ENTITY|<(?:script|foreignObject|iframe|object|embed|image|use|style|animate|set)\b|\bon[a-z]+\s*=|(?:href|src)\s*=|url\s*\(|javascript:/i.test(svg))throw Error('SVG must contain self-contained vector paths without scripts or external assets.');return 'image/svg+xml';}throw Error('Upload PNG, JPG, WebP, SVG or PDF files.');}
async function storeFile(env,sessionId,data,name,type,role,designId=null){const id=crypto.randomUUID(),key='studio/'+sessionId+'/'+id;await env.FILES.put(key,data,{httpMetadata:{contentType:type}});try{await env.DB.prepare('INSERT INTO studio_files (id,session_id,design_id,object_key,name,mime,size,role,created_at) VALUES (?,?,?,?,?,?,?,?,?)').bind(id,sessionId,designId,key,name,type,data.byteLength??data.length,role,now()).run();}catch(e){await env.FILES.delete(key);throw e;}return {id,name,mime:type,size:data.byteLength??data.length,role};}
async function embedAssets(env,design,sessionId){const out={};for(const id of new Set(design.sides.flatMap(s=>s.layers.filter(l=>l.type==='image').map(l=>l.assetId)))){const row=await fileRow(env.DB,id,sessionId,false);if(!row.mime.startsWith('image/'))throw Error('Use image uploads in the design canvas.');const object=await env.FILES.get(row.object_key);if(!object)throw Error('An uploaded image is unavailable.');const data=new Uint8Array(await object.arrayBuffer());let encoded='';for(let i=0;i<data.length;i+=16384)encoded+=String.fromCharCode(...data.subarray(i,i+16384));out[id]='data:'+row.mime+';base64,'+btoa(encoded);}return out;}
async function fontStyles(env,request){let css='';for(const [name,file] of [['Inter','inter-latin.woff2'],['Vazirmatn','vazirmatn.woff2']]){const r=await env.ASSETS.fetch(new Request(new URL('/satin/fonts/'+file,request.url)));if(r.ok){const bytes=new Uint8Array(await r.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));css+=`@font-face{font-family:'${name}';src:url('data:font/woff2;base64,${btoa(raw)}') format('woff2');font-weight:100 900;}`;}}return css;}
